svg.script:
const root = document.documentElement;
const minecart = root.querySelector('.minecart');
const poweredLayer = root.querySelector('.powered-rails');
const tileSize = 16;
const boostTail = 48;
const restartDelay = 1000;
const isPowered = () => root.matches(':hover');
let poweredZones = [];
let isRunning = false;
let restartTimer = 0;

const cancelRestart = () => {
  if (restartTimer) {
    window.clearTimeout(restartTimer);
    restartTimer = 0;
  }
};

const queueNextMinecart = () => {
  cancelRestart();
  if (!isPowered()) return;

  restartTimer = window.setTimeout(() => {
    restartTimer = 0;
    if (isPowered()) runMinecart();
  }, restartDelay);
};

const shuffled = (values) => {
  const copy = [...values];
  for (let index = copy.length - 1; index > 0; index -= 1) {
    const randomIndex = Math.floor(Math.random() * (index + 1));
    [copy[index], copy[randomIndex]] = [copy[randomIndex], copy[index]];
  }
  return copy;
};

const buildPoweredRails = () => {
  const width = root.getBoundingClientRect().width;
  const tileCount = Math.max(8, Math.ceil(width / tileSize));
  const firstTile = 2;
  const lastTile = Math.max(firstTile, tileCount - 7);
  const candidates = Array.from(
    { length: lastTile - firstTile + 1 },
    (_, index) => firstTile + index
  );
  const targetCount = Math.max(
    2,
    Math.min(8, Math.round(tileCount * 0.13 + Math.random()))
  );
  const selected = [];

  shuffled(candidates).forEach((tileIndex) => {
    if (
      selected.length < targetCount &&
      selected.every((selectedIndex) => Math.abs(selectedIndex - tileIndex) > 2)
    ) {
      selected.push(tileIndex);
    }
  });

  shuffled(candidates).forEach((tileIndex) => {
    if (selected.length < targetCount && !selected.includes(tileIndex)) {
      selected.push(tileIndex);
    }
  });

  selected.sort((left, right) => left - right);
  poweredLayer.replaceChildren();
  const template = root.querySelector(poweredLayer.dataset.template);

  selected.forEach((tileIndex) => {
    const poweredRail = template.cloneNode(true);
    poweredRail.removeAttribute('id');
    poweredRail.classList.add('powered-segment');
    poweredRail.setAttribute('transform', `translate(${tileIndex * tileSize} 0)`);
    poweredLayer.append(poweredRail);
  });

  poweredZones = selected.map((tileIndex) => ({
    start: tileIndex * tileSize,
    end: (tileIndex + 1) * tileSize + boostTail
  }));
  root.dataset.poweredTiles = selected.join(',');
};

const runMinecart = () => {
  if (isRunning) return;

  cancelRestart();
  isRunning = true;
  root.classList.add('is-running');
  root.dataset.boostSeen = 'false';
  root.dataset.returnedToCruise = 'false';
  root.dataset.maxSpeedFactor = '1';
  minecart.style.opacity = '1';

  const width = root.getBoundingClientRect().width;
  const travelDistance = width + 32;
  const baseSpeed = travelDistance / 2400;
  let distance = 0;
  let speedFactor = 1;
  let lastTime = 0;
  let boostSeen = false;
  let returnedToCruise = false;
  let maxSpeedFactor = 1;

  const frame = (time) => {
    if (!lastTime) lastTime = time;
    const delta = Math.min(34, time - lastTime);
    lastTime = time;

    const cartCenter = -8 + distance;
    const isBoosted = isPowered() && poweredZones.some(
      (zone) => cartCenter >= zone.start && cartCenter <= zone.end
    );
    const targetFactor = isBoosted ? 2 : 1;
    speedFactor += (targetFactor - speedFactor) * Math.min(1, delta / 70);
    distance += baseSpeed * speedFactor * delta;
    maxSpeedFactor = Math.max(maxSpeedFactor, speedFactor);

    if (isBoosted) boostSeen = true;
    if (boostSeen && !isBoosted && speedFactor < 1.08) returnedToCruise = true;

    minecart.style.transform = `translateX(${Math.round(distance)}px)`;

    if (distance < travelDistance) {
      requestAnimationFrame(frame);
      return;
    }

    minecart.style.opacity = '0';
    minecart.style.transform = 'translateX(0)';
    root.classList.remove('is-running');
    root.dataset.boostSeen = String(boostSeen);
    root.dataset.returnedToCruise = String(returnedToCruise);
    root.dataset.maxSpeedFactor = maxSpeedFactor.toFixed(2);
    isRunning = false;
    queueNextMinecart();
  };

  requestAnimationFrame(frame);
};

requestAnimationFrame(buildPoweredRails);
root.addEventListener('pointerenter', () => {
  cancelRestart();
  runMinecart();
});
root.addEventListener('pointerleave', cancelRestart);
root.addEventListener('focus', runMinecart);
